'use client';

import { useEffect, useId, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import './project-brief-builder.css';

/** One uniquely identified service, budget range, or timeline choice. */
export interface ProjectBriefOption {
  id: string;
  label: string;
  description?: string;
}

/** Serializable enquiry data. Choice values contain the supplied option ids. */
export interface ProjectBrief {
  services: string[];
  description: string;
  budget: string;
  timeline: string;
  name: string;
  email: string;
  company: string;
}

export interface ProjectBriefBuilderProps {
  services: ProjectBriefOption[];
  budgets: ProjectBriefOption[];
  timelines: ProjectBriefOption[];
  /** Connect your own endpoint here. Reject to keep the brief and show a retry message. */
  onSubmit: (brief: ProjectBrief) => void | Promise<void>;
  studioName?: string;
  eyebrow?: string;
  title?: string;
  description?: string;
  availability?: string;
  submitLabel?: string;
  successTitle?: string;
  successMessage?: string;
  className?: string;
}

type BriefField = keyof ProjectBrief;
type BriefErrors = Partial<Record<BriefField, string>>;
const blankBrief = (): ProjectBrief => ({ services: [], description: '', budget: '', timeline: '', name: '', email: '', company: '' });
const steps = [{ label: 'The project', note: 'A little about your idea' }, { label: 'The details', note: 'A few practical things' }, { label: 'The introduction', note: 'Check it, then say hello' }];

/** A three-step enquiry form. Submission runs only through the required callback. */
export function ProjectBriefBuilder({
  services, budgets, timelines, onSubmit, studioName = 'Your studio', eyebrow = 'LET’S DEFINE YOUR NEXT PROJECT',
  title = 'Your next project.', description = 'Tell us what you’re planning, what you need, and when you’d like to begin.', availability = 'Open for new collaborations',
  submitLabel = 'Send your brief', successTitle = 'Brief received.', successMessage = 'Your brief has been submitted. Thank you for the introduction.', className = '',
}: ProjectBriefBuilderProps) {
  const uid = useId();
  const [brief, setBrief] = useState<ProjectBrief>(blankBrief);
  const [step, setStep] = useState(0);
  const [errors, setErrors] = useState<BriefErrors>({});
  const [status, setStatus] = useState<'idle' | 'pending' | 'error' | 'success'>('idle');
  const heading = useRef<HTMLHeadingElement>(null);
  const form = useRef<HTMLFormElement>(null);
  const focusTarget = useRef<BriefField | 'heading' | null>(null);
  const locked = useRef(false);
  const mounted = useRef(true);

  useEffect(() => { mounted.current = true; return () => { mounted.current = false; }; }, []);
  useEffect(() => {
    const target = focusTarget.current;
    if (!target) return;
    focusTarget.current = null;
    if (target === 'heading') heading.current?.focus();
    else form.current?.querySelector<HTMLElement>(`[name="${target}"]`)?.focus();
  }, [step, errors, status]);

  const labelFor = (options: ProjectBriefOption[], id: string) => options.find(option => option.id === id)?.label ?? 'Selection no longer available';
  const availableServices = brief.services.filter(id => services.some(option => option.id === id));
  const choiceValue = (field: 'budget' | 'timeline') => (field === 'budget' ? budgets : timelines).some(option => option.id === brief[field]) ? brief[field] : '';
  function update<K extends BriefField>(field: K, value: ProjectBrief[K]) {
    setBrief(current => ({ ...current, [field]: value }));
    setErrors(current => ({ ...current, [field]: undefined }));
    if (status === 'error') setStatus('idle');
  }
  function validate(target: number): BriefErrors {
    const next: BriefErrors = {};
    if (target === 0 || target === 2) {
      if (!availableServices.length) next.services = 'Choose at least one service.';
      if (brief.description.trim().length < 20) next.description = 'Give us a little more context — at least 20 characters.';
    }
    if (target === 1 || target === 2) {
      if (!budgets.some(option => option.id === brief.budget)) next.budget = 'Choose a budget range.';
      if (!timelines.some(option => option.id === brief.timeline)) next.timeline = 'Choose a timeline.';
      if (!brief.name.trim()) next.name = 'Tell us your name.';
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(brief.email.trim())) next.email = 'Enter a valid email address.';
    }
    return next;
  }
  function go(next: number) {
    if (locked.current) return;
    focusTarget.current = 'heading';
    setErrors({});
    setStatus('idle');
    setStep(next);
  }
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (locked.current) return;
    const nextErrors = validate(step);
    const first = Object.keys(nextErrors)[0] as BriefField | undefined;
    if (first) {
      focusTarget.current = first;
      setErrors(nextErrors);
      if (step === 2) setStep(first === 'services' || first === 'description' ? 0 : 1);
      return;
    }
    if (step < 2) { go(step + 1); return; }
    locked.current = true;
    setStatus('pending');
    const submission: ProjectBrief = { ...brief, services: availableServices, name: brief.name.trim(), email: brief.email.trim(), company: brief.company.trim(), description: brief.description.trim() };
    try {
      await onSubmit(submission);
      if (mounted.current) { setBrief(submission); focusTarget.current = 'heading'; setStatus('success'); }
    } catch {
      if (mounted.current) setStatus('error');
    } finally {
      locked.current = false;
    }
  }
  function reset() {
    if (locked.current) return;
    setBrief(blankBrief());
    setErrors({});
    focusTarget.current = 'heading';
    setStatus('idle');
    setStep(0);
  }
  const fieldHelp = (field: BriefField) => errors[field] ? `${uid}-${field}-error` : undefined;
  const unavailable = !services.length || !budgets.length || !timelines.length;
  const success = status === 'success';

  return <section className={`ac-brief ${className}`.trim()} aria-labelledby={`${uid}-title`}>
    <div className="ac-brief-surface">
      <header className="ac-brief-masthead"><span className="ac-brief-brand">{studioName}<span aria-hidden="true">®</span></span><span className="ac-brief-availability"><i aria-hidden="true" />{availability}</span></header>
      <div className="ac-brief-layout">
        <aside className="ac-brief-intro">
          <p className="ac-brief-eyebrow">{eyebrow}</p>
          <h2 id={`${uid}-title`}>{title}</h2><p className="ac-brief-description">{description}</p>
          <ol className="ac-brief-progress" aria-label="Brief progress">{steps.map((item, index) => <li key={item.label} aria-current={!success && step === index ? 'step' : undefined} data-complete={success || index < step} data-active={!success && index === step}><span className="ac-brief-step-number" aria-hidden="true">{success || index < step ? '✓' : `0${index + 1}`}</span><span><strong>{item.label}</strong><small>{item.note}</small></span><span className="ac-brief-step-arrow" aria-hidden="true">↗</span></li>)}</ol>
          <div className="ac-brief-note"><span aria-hidden="true">✳</span><p>Every worthwhile project<br />starts with a first hello.</p></div>
        </aside>
        <div className="ac-brief-panel">
          {unavailable ? <div className="ac-brief-unavailable"><h3 ref={heading} tabIndex={-1}>Let’s get ready.</h3><p>Add at least one service, budget range, and timeline to open this brief.</p></div> : success ? <div className="ac-brief-success">
            <span className="ac-brief-success-mark" aria-hidden="true">↗</span><p className="ac-brief-eyebrow">INTRODUCTION COMPLETE</p><h3 ref={heading} tabIndex={-1}>{successTitle}</h3><p>{successMessage}</p>
            <dl className="ac-brief-receipt"><div><dt>Project</dt><dd>{availableServices.map(id => labelFor(services, id)).join(' + ')}</dd></div><div><dt>From</dt><dd>{brief.name}<span>{brief.email}</span></dd></div><div><dt>Budget / timing</dt><dd>{labelFor(budgets, brief.budget)}<span>{labelFor(timelines, brief.timeline)}</span></dd></div><div><dt>The idea</dt><dd className="ac-brief-receipt-idea">{brief.description}</dd></div></dl>
            <button className="ac-brief-text-button" type="button" onClick={reset}>Start another brief <span aria-hidden="true">↗</span></button>
          </div> : <form ref={form} noValidate onSubmit={submit} aria-labelledby={`${uid}-step-title`} aria-busy={status === 'pending'}>
            <header className="ac-brief-panel-heading"><p className="ac-brief-eyebrow">0{step + 1} / 03 — {step === 0 ? 'THE POSSIBILITIES' : step === 1 ? 'THE PRACTICALITIES' : 'THE FIRST HELLO'}</p><h3 id={`${uid}-step-title`} ref={heading} tabIndex={-1}>{step === 0 ? 'What are we making?' : step === 1 ? 'Make it a little more real.' : 'Does this feel right?'}</h3><p>{step === 0 ? 'One thing or a few. Choose what you have in mind.' : step === 1 ? 'Estimates are fine. We can refine the budget and timing together.' : 'Review the scope, timing, and contact details before you send.'}</p></header>
            <fieldset className="ac-brief-fields" disabled={status === 'pending'}>
              <legend className="ac-brief-sr-only">{steps[step].label}</legend>
              {step === 0 && <>
                <fieldset className="ac-brief-service-group" aria-describedby={fieldHelp('services')}><legend>I’m looking for <span>(choose one or more)</span></legend><div className="ac-brief-services">{services.map(service => <label className="ac-brief-service" key={service.id}><input type="checkbox" name="services" value={service.id} checked={brief.services.includes(service.id)} aria-invalid={!!errors.services} onChange={event => update('services', event.target.checked ? [...brief.services, service.id] : brief.services.filter(id => id !== service.id))} /><span><strong>{service.label}</strong>{service.description && <small>{service.description}</small>}</span><i aria-hidden="true">{brief.services.includes(service.id) ? '✓' : '+'}</i></label>)}</div>{errors.services && <p className="ac-brief-error" id={fieldHelp('services')}>{errors.services}</p>}</fieldset>
                <label className="ac-brief-field" htmlFor={`${uid}-description`}><span>A little about your project <i>Required</i></span><textarea id={`${uid}-description`} name="description" rows={3} maxLength={4000} value={brief.description} onChange={event => update('description', event.target.value)} placeholder="The idea, the ambition, the thing you’d love to change…" aria-required="true" aria-invalid={!!errors.description} aria-describedby={fieldHelp('description')} />{errors.description && <small className="ac-brief-error" id={fieldHelp('description')}>{errors.description}</small>}</label>
              </>}
              {step === 1 && <>
                <div className="ac-brief-field-pair">{([{ key: 'budget', label: 'Your budget', options: budgets, placeholder: 'Select a range' }, { key: 'timeline', label: 'Your timeline', options: timelines, placeholder: 'Select a timeframe' }] as const).map(field => <label key={field.key} className="ac-brief-field" htmlFor={`${uid}-${field.key}`}><span>{field.label} <i>Required</i></span><select id={`${uid}-${field.key}`} name={field.key} value={choiceValue(field.key)} onChange={event => update(field.key, event.target.value)} aria-required="true" aria-invalid={!!errors[field.key]} aria-describedby={fieldHelp(field.key)}><option value="" disabled>{field.placeholder}</option>{field.options.map(option => <option key={option.id} value={option.id}>{option.label}</option>)}</select>{errors[field.key] && <small className="ac-brief-error" id={fieldHelp(field.key)}>{errors[field.key]}</small>}</label>)}</div>
                <div className="ac-brief-field-pair">{([{ key: 'name', label: 'Your name', type: 'text', autoComplete: 'name', placeholder: 'Alex Morgan' }, { key: 'email', label: 'Email address', type: 'email', autoComplete: 'email', placeholder: 'alex@yourcompany.com' }] as const).map(field => <label key={field.key} className="ac-brief-field" htmlFor={`${uid}-${field.key}`}><span>{field.label} <i>Required</i></span><input id={`${uid}-${field.key}`} name={field.key} type={field.type} autoComplete={field.autoComplete} maxLength={field.key === 'email' ? 254 : 120} value={brief[field.key]} onChange={event => update(field.key, event.target.value)} placeholder={field.placeholder} aria-required="true" aria-invalid={!!errors[field.key]} aria-describedby={fieldHelp(field.key)} />{errors[field.key] && <small className="ac-brief-error" id={fieldHelp(field.key)}>{errors[field.key]}</small>}</label>)}</div>
                <label className="ac-brief-field" htmlFor={`${uid}-company`}><span>Company or website <i>Optional</i></span><input id={`${uid}-company`} name="company" autoComplete="organization" maxLength={200} value={brief.company} onChange={event => update('company', event.target.value)} placeholder="Where you call home on the internet" /></label>
              </>}
              {step === 2 && <div className="ac-brief-review"><div className="ac-brief-review-group"><div className="ac-brief-review-label"><span>THE PROJECT</span><button type="button" className="ac-brief-text-button" onClick={() => go(0)}>Edit project <span aria-hidden="true">↗</span></button></div><div className="ac-brief-review-chips">{availableServices.length ? availableServices.map(id => <span key={id}>{labelFor(services, id)}</span>) : <span>Choose a service</span>}</div><p className="ac-brief-review-description">{brief.description}</p></div><div className="ac-brief-review-group"><div className="ac-brief-review-label"><span>THE DETAILS</span><button type="button" className="ac-brief-text-button" onClick={() => go(1)}>Edit details <span aria-hidden="true">↗</span></button></div><dl><div><dt>Budget</dt><dd>{labelFor(budgets, brief.budget)}</dd></div><div><dt>Timeline</dt><dd>{labelFor(timelines, brief.timeline)}</dd></div><div><dt>Contact</dt><dd>{brief.name}<span>{brief.email}</span>{brief.company && <span>{brief.company}</span>}</dd></div></dl></div></div>}
            </fieldset>
            {status === 'error' && <p className="ac-brief-submit-error" role="alert">We couldn’t submit your brief. Your details are still here — please try again.</p>}
            <footer className="ac-brief-actions"><span className="ac-brief-action-note">{step === 0 ? 'A few details. About 2 minutes.' : step === 1 ? 'Almost there. Just the introduction left.' : 'Ready when you are.'}</span><div>{step > 0 && <button type="button" className="ac-brief-back" disabled={status === 'pending'} onClick={() => go(step - 1)}><span aria-hidden="true">←</span> Back</button>}<button className="ac-brief-next" type="submit" disabled={status === 'pending'}><span>{status === 'pending' ? 'Submitting…' : step < 2 ? 'Continue' : submitLabel}</span><span aria-hidden="true">↗</span></button></div></footer>
            <span className="ac-brief-sr-only" role="status">{status === 'pending' ? 'Submitting your brief. Please wait.' : ''}</span>
          </form>}
        </div>
      </div><footer className="ac-brief-colophon"><span>A LITTLE CONTEXT. A LOT OF POSSIBILITY.</span><span>{studioName} / LET’S MAKE IT MATTER</span></footer>
    </div>
  </section>;
}

.ac-brief {
  --ac-brief-paper: #f0eee5;
  --ac-brief-ink: #203c31;
  --ac-brief-muted: #636b60;
  --ac-brief-line: #c9cdc0;
  --ac-brief-accent: #d4e6ac;
  --ac-brief-radius: 0px;
  container-type: inline-size;
  width: 100%;
  background: var(--ac-brief-paper);
  color: var(--ac-brief-ink);
  font-family: Arial, Helvetica, sans-serif;
  line-height: 1.5;
  border-radius: var(--ac-brief-radius);
}
.ac-brief *, .ac-brief *::before, .ac-brief *::after { box-sizing: border-box; }
.ac-brief button, .ac-brief input, .ac-brief select, .ac-brief textarea { font: inherit; }
.ac-brief button { cursor: pointer; }
.ac-brief button:disabled { cursor: wait; opacity: .65; }
.ac-brief button:focus-visible, .ac-brief input:focus-visible, .ac-brief select:focus-visible, .ac-brief textarea:focus-visible { outline: 2px solid var(--ac-brief-ink); outline-offset: 4px; }
.ac-brief h3[tabindex]:focus { outline: none; }
.ac-brief-surface { max-width: 1680px; margin-inline: auto; padding: 0 clamp(24px, 4.1cqi, 70px); }
.ac-brief-masthead { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 30px 0; border-bottom: 1px solid var(--ac-brief-line); }
.ac-brief-brand { display: flex; align-items: flex-start; gap: 4px; font-size: 27px; font-weight: 700; line-height: 1; letter-spacing: -.065em; }
.ac-brief-brand > span { font-size: 10px; margin-top: 2px; letter-spacing: 0; }
.ac-brief-availability { display: flex; align-items: center; gap: 8px; font-size: 10px; }
.ac-brief-availability i { display: inline-block; width: 6px; height: 6px; flex-shrink: 0; border-radius: 50%; background: var(--ac-brief-ink); box-shadow: 0 0 0 4px color-mix(in srgb, var(--ac-brief-ink) 8%, transparent); }
.ac-brief-layout { display: grid; grid-template-columns: minmax(0, .9fr) minmax(0, 1fr); gap: clamp(38px, 7cqi, 110px); padding: 64px 0 56px; }
.ac-brief-intro { min-width: 0; display: flex; flex-direction: column; align-items: flex-start; }
.ac-brief-eyebrow { margin: 0 0 18px; font-size: 9px; letter-spacing: .095em; line-height: 1.5; font-weight: 400; }
.ac-brief-intro h2 { max-width: 9ch; margin: 0; font-family: Georgia, 'Times New Roman', serif; font-size: clamp(48px, 5.65cqi, 86px); font-weight: 400; line-height: 1.02; letter-spacing: -.065em; text-wrap: balance; }
.ac-brief-description { max-width: 27ch; margin: 22px 0 0; color: var(--ac-brief-muted); font-size: clamp(13px, 1.1cqi, 16px); line-height: 1.65; }
.ac-brief-progress { width: 100%; max-width: 360px; list-style: none; margin: 43px 0 0; padding: 0; }
.ac-brief-progress li { display: flex; align-items: center; gap: 16px; min-height: 67px; border-top: 1px solid var(--ac-brief-line); color: var(--ac-brief-muted); }
.ac-brief-progress li:last-child { border-bottom: 1px solid var(--ac-brief-line); }
.ac-brief-step-number { display: grid; place-items: center; flex-shrink: 0; width: 30px; height: 30px; border: 1px solid var(--ac-brief-line); border-radius: 50%; font-size: 10px; }
.ac-brief-progress strong { display: block; font-size: 12px; font-weight: 400; }
.ac-brief-progress small { display: block; font-size: 9px; opacity: .8; margin-top: 2px; }
.ac-brief-step-arrow { margin-left: auto; font-size: 20px; opacity: 0; }
.ac-brief-progress li[data-active='true'] { color: var(--ac-brief-ink); }
.ac-brief-progress li[data-active='true'] .ac-brief-step-number { border-color: var(--ac-brief-ink); background: var(--ac-brief-ink); color: var(--ac-brief-paper); }
.ac-brief-progress li[data-active='true'] .ac-brief-step-arrow { opacity: 1; }
.ac-brief-progress li[data-complete='true'] .ac-brief-step-number { background: var(--ac-brief-accent); border-color: transparent; color: var(--ac-brief-ink); }
.ac-brief-note { display: flex; gap: 16px; align-items: center; margin-top: auto; padding-top: 40px; }
.ac-brief-note > span { font-size: 46px; line-height: 1; font-family: Georgia, serif; }
.ac-brief-note p { margin: 0; color: var(--ac-brief-muted); font-size: 10px; line-height: 1.6; }
.ac-brief-panel { min-width: 0; }
.ac-brief-panel form { display: flex; flex-direction: column; min-height: 560px; }
.ac-brief-panel-heading { margin-bottom: 28px; }
.ac-brief-panel-heading .ac-brief-eyebrow { margin-bottom: 15px; color: var(--ac-brief-muted); font-size: 8px; }
.ac-brief-panel h3 { margin: 0; font-size: clamp(25px, 2.65cqi, 38px); font-weight: 400; letter-spacing: -.055em; line-height: 1.12; text-wrap: balance; }
.ac-brief-panel-heading > p:last-child { color: var(--ac-brief-muted); font-size: 11px; line-height: 1.65; margin: 12px 0 0; }
.ac-brief-fields { border: 0; margin: 0; padding: 0; min-width: 0; }
.ac-brief-service-group { padding: 0; border: 0; margin: 0 0 27px; min-width: 0; }
.ac-brief-service-group legend { font-size: 10px; margin-bottom: 11px; padding: 0; }
.ac-brief-service-group legend > span { color: var(--ac-brief-muted); margin-left: 3px; font-size: 9px; }
.ac-brief-services { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.ac-brief-service { position: relative; display: flex; align-items: center; gap: 12px; min-width: 0; min-height: 67px; padding: 14px 14px; border: 1px solid var(--ac-brief-line); border-radius: 2px; cursor: pointer; transition: background .2s, border-color .2s; }
.ac-brief-service > input { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer; }
.ac-brief-service:has(input:focus-visible) { outline: 2px solid var(--ac-brief-ink); outline-offset: 4px; }
.ac-brief-service:has(input:checked) { border-color: var(--ac-brief-ink); background: var(--ac-brief-accent); }
.ac-brief-service:has(input[aria-invalid='true']) { border-color: #a23e2f; }
.ac-brief-service:has(input:checked[aria-invalid='true']) { border-color: var(--ac-brief-ink); }
.ac-brief-service strong { display: block; font-size: 12px; line-height: 1.3; font-weight: 400; }
.ac-brief-service small { display: block; color: var(--ac-brief-muted); font-size: 8px; line-height: 1.4; margin-top: 4px; }
.ac-brief-service i { margin-left: auto; font-size: 18px; font-style: normal; flex-shrink: 0; }
.ac-brief-field { display: flex; flex-direction: column; min-width: 0; margin: 0 0 24px; }
.ac-brief-field > span { display: flex; justify-content: space-between; gap: 8px; font-size: 10px; margin-bottom: 9px; }
.ac-brief-field > span > i { font-style: normal; color: var(--ac-brief-muted); font-size: 8px; }
.ac-brief-field input, .ac-brief-field select, .ac-brief-field textarea { display: block; width: 100%; min-width: 0; min-height: 48px; border: 0; border-bottom: 1px solid var(--ac-brief-line); border-radius: 0; background: transparent; padding: 12px 0; color: var(--ac-brief-ink); font-size: 12px; line-height: 1.5; }
.ac-brief-field select { cursor: pointer; padding-right: 22px; }
.ac-brief-field select option { background: var(--ac-brief-paper); color: var(--ac-brief-ink); }
.ac-brief-field textarea { resize: vertical; min-height: 105px; max-height: 440px; }
.ac-brief-field input::placeholder, .ac-brief-field textarea::placeholder { color: var(--ac-brief-muted); opacity: .85; }
.ac-brief-field [aria-invalid='true'] { border-color: #a23e2f; }
.ac-brief-field-pair { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px; }
.ac-brief-error { margin: 7px 0 0; color: #963b2d; font-size: 10px; line-height: 1.5; }
.ac-brief-actions { display: flex; align-items: center; gap: 20px; justify-content: space-between; margin-top: auto; padding-top: 25px; border-top: 1px solid var(--ac-brief-line); }
.ac-brief-action-note { font-size: 9px; color: var(--ac-brief-muted); }
.ac-brief-actions > div { display: flex; align-items: center; gap: 16px; }
.ac-brief-next { display: flex; align-items: center; justify-content: space-between; gap: 35px; min-height: 49px; min-width: 148px; padding: 13px 17px; border: 1px solid var(--ac-brief-ink); border-radius: 2px; background: var(--ac-brief-ink); color: var(--ac-brief-paper); font-size: 11px; text-align: left; transition: background .2s, color .2s; }
.ac-brief-next > span:last-child { font-size: 20px; line-height: 1; }
.ac-brief-back { display: flex; align-items: center; gap: 7px; min-height: 44px; padding: 4px; background: none; border: none; color: var(--ac-brief-ink); font-size: 10px; }
.ac-brief-colophon { display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: 55px; padding: 15px 0; border-top: 1px solid var(--ac-brief-line); color: var(--ac-brief-muted); font-size: 7px; letter-spacing: .07em; }
.ac-brief-colophon > span:last-child { text-align: right; }
.ac-brief-review-group { border-top: 1px solid var(--ac-brief-line); padding: 0 0 23px; }
.ac-brief-review-label { display: flex; align-items: center; justify-content: space-between; gap: 20px; min-height: 50px; }
.ac-brief-review-label > span { font-size: 8px; letter-spacing: .08em; color: var(--ac-brief-muted); }
.ac-brief-text-button { display: inline-flex; align-items: center; justify-content: flex-start; gap: 10px; min-height: 44px; padding: 0; background: transparent; border: none; color: var(--ac-brief-ink); font-size: 10px; text-decoration: underline; text-underline-offset: 4px; }
.ac-brief-text-button > span { font-size: 17px; text-decoration: none; }
.ac-brief-review-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.ac-brief-review-chips > span { padding: 5px 9px; background: var(--ac-brief-accent); font-size: 10px; border-radius: 2px; }
.ac-brief-review-description { color: var(--ac-brief-ink); font-size: 12px; line-height: 1.65; white-space: pre-wrap; overflow-wrap: anywhere; }
.ac-brief-review dl, .ac-brief-receipt { margin: 0; }
.ac-brief-review dl > div { display: grid; grid-template-columns: 72px minmax(0, 1fr); gap: 15px; padding: 7px 0; font-size: 11px; }
.ac-brief-review dt, .ac-brief-receipt dt { color: var(--ac-brief-muted); }
.ac-brief-review dd, .ac-brief-receipt dd { margin: 0; overflow-wrap: anywhere; }
.ac-brief-review dd > span, .ac-brief-receipt dd > span { display: block; color: var(--ac-brief-muted); }
.ac-brief-submit-error { margin: 0 0 20px; padding: 12px 14px; background: #f0dace; color: #843225; font-size: 11px; }
.ac-brief-success { padding-top: 4px; min-height: 560px; }
.ac-brief-success-mark { display: grid; place-items: center; width: 60px; height: 60px; margin-bottom: 35px; background: var(--ac-brief-accent); border-radius: 50%; font-size: 34px; }
.ac-brief-success > p:not(.ac-brief-eyebrow) { max-width: 38ch; color: var(--ac-brief-muted); font-size: 13px; line-height: 1.6; }
.ac-brief-receipt { margin: 28px 0 20px; }
.ac-brief-receipt > div { display: grid; grid-template-columns: 95px minmax(0, 1fr); gap: 18px; padding: 13px 0; border-top: 1px solid var(--ac-brief-line); font-size: 11px; line-height: 1.5; }
.ac-brief-receipt-idea { white-space: pre-wrap; }
.ac-brief-unavailable { padding: 30px 0; }
.ac-brief-unavailable p { color: var(--ac-brief-muted); font-size: 13px; }
.ac-brief-sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
@media (hover: hover) {
  .ac-brief-service:hover { border-color: var(--ac-brief-ink); }
  .ac-brief-next:hover:not(:disabled) { background: var(--ac-brief-accent); color: var(--ac-brief-ink); }
}
@container (width < 800px) {
  .ac-brief-layout { gap: 30px; padding: 42px 0 38px; grid-template-columns: minmax(0, .72fr) minmax(0, 1fr); }
  .ac-brief-surface { padding-inline: 24px; }
  .ac-brief-intro h2 { font-size: 48px; }
  .ac-brief-description { font-size: 12px; }
  .ac-brief-panel-heading { margin-bottom: 24px; }
  .ac-brief-panel h3 { font-size: 26px; }
  .ac-brief-services { grid-template-columns: 1fr; }
  .ac-brief-service { min-height: 54px; padding: 11px 12px; }
  .ac-brief-panel form { min-height: 610px; }
  .ac-brief-field-pair { grid-template-columns: 1fr; gap: 0; }
  .ac-brief-actions { align-items: flex-end; }
  .ac-brief-action-note { max-width: 11ch; }
  .ac-brief-actions > div { gap: 10px; }
  .ac-brief-next { min-width: 115px; gap: 15px; }
}
@container (width < 580px) {
  .ac-brief-surface { padding-inline: 24px; }
  .ac-brief-masthead { padding-block: 23px; }
  .ac-brief-brand { font-size: 24px; }
  .ac-brief-availability { font-size: 8px; max-width: 18ch; }
  .ac-brief-layout { grid-template-columns: minmax(0, 1fr); gap: 35px; padding-top: 36px; }
  .ac-brief-intro h2 { font-size: clamp(44px, 12cqi, 66px); max-width: 10ch; }
  .ac-brief-eyebrow { font-size: 8px; margin-bottom: 17px; }
  .ac-brief-description { margin-top: 17px; max-width: 31ch; }
  .ac-brief-progress { display: flex; max-width: none; margin-top: 27px; }
  .ac-brief-progress li { min-width: 0; flex: 1; align-items: center; gap: 8px; min-height: 46px; border-top: 0; border-bottom: 1px solid var(--ac-brief-line); }
  .ac-brief-progress li[data-active='true'] { border-bottom-color: var(--ac-brief-ink); }
  .ac-brief-progress li:last-child { flex: 1.2; }
  .ac-brief-step-number { width: 23px; height: 23px; font-size: 8px; }
  .ac-brief-progress strong { font-size: 8px; }
  .ac-brief-progress small, .ac-brief-step-arrow, .ac-brief-note { display: none; }
  .ac-brief-panel form { min-height: 0; }
  .ac-brief-panel h3 { font-size: 30px; }
  .ac-brief-panel-heading > p:last-child { font-size: 12px; }
  .ac-brief-services { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .ac-brief-service { min-height: 69px; gap: 5px; padding: 12px 10px; }
  .ac-brief-service strong { font-size: 11px; }
  .ac-brief-service small { font-size: 8px; }
  .ac-brief-service i { font-size: 16px; }
  .ac-brief-field input, .ac-brief-field select, .ac-brief-field textarea { font-size: 16px; }
  .ac-brief-field > span, .ac-brief-service-group legend { font-size: 11px; }
  .ac-brief-actions { margin-top: 5px; padding-top: 20px; }
  .ac-brief-actions > div { gap: 14px; }
  .ac-brief-next { min-width: 133px; font-size: 11px; }
  .ac-brief-success { min-height: 0; }
  .ac-brief-colophon { font-size: 6px; }
}
@container (width < 340px) {
  .ac-brief-surface { padding-inline: 17px; }
  .ac-brief-services { grid-template-columns: 1fr; }
  .ac-brief-service { min-height: 56px; }
  .ac-brief-progress { gap: 7px; }
  .ac-brief-progress li { flex-direction: column; align-items: flex-start; padding-bottom: 9px; gap: 6px; }
  .ac-brief-action-note { display: none; }
  .ac-brief-actions { justify-content: flex-end; }
}
@media (prefers-reduced-motion: reduce) { .ac-brief-service, .ac-brief-next { transition: none; } }
